import { analyzeUrl, hashFile, createCase, validateWorkspace, exportReport, encryptWorkspace, decryptWorkspace, TYPES, PLAYBOOKS } from './core.mjs';
import { isWorkspaceDirty, readArchiveInput, saveCiphertext, eraseCiphertext } from './vault.mjs';
import {emptyDraft, startIncidentDraft, hasPendingDrafts} from './drafts.mjs';
import {REPORT_FIELDS, findReportingRoutes, getReportingRoute, buildReportingPacket} from './reporting.mjs';

const $ = selector => document.querySelector(selector);
const escape = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const routes = [['overview','Home'],['link','Check a link'],['evidence','Fingerprint a file'],['cases','Incidents'],['library','Guides']];
const sections = {overview:'overview',link:'link',tools:'link',evidence:'evidence',cases:'cases',case:'cases',edit:'cases',new:'cases',library:'library',help:'library',report:'library',vault:'vault'};
const pageTitles = {overview:'Home',link:'Check a link',tools:'Check a link',evidence:'Fingerprint a file',cases:'Incidents',case:'Incident',edit:'Edit incident',new:'New incident',library:'Guides and limits',help:'Response steps',report:'Report or recover',vault:'Your data'};
const storageKey = 'usualcybersec-vault-v1';
let workspace = {version:1,cases:[]};
let savedSnapshot = null;
let vaultRaw = null;
let vaultChanged = false;
let storageAvailable = true;
try { vaultRaw = localStorage.getItem(storageKey); } catch { storageAvailable = false; }
let latestEvidence = null;
let pendingFile = null;
let drafts = emptyDraft();
let caseEditDrafts = Object.create(null);
let attachmentDraft = {caseId:'',sourceUrl:'',notes:''};
let lastUrl = null;
let operation = 0;
let busy = false;
let noticeTimer;
let reportingSelection = {caseId:'',issue:'all',routeId:'',disclosure:{}};
let renderedRoute = '';
function resetReporting(){reportingSelection={caseId:'',issue:'all',routeId:'',disclosure:{}};}
function resetAttachmentDraft(){attachmentDraft={caseId:'',sourceUrl:'',notes:''};}
const hasDraftWork = () => hasPendingDrafts(drafts,pendingFile,caseEditDrafts,attachmentDraft);
const date = value => new Date(value).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'});
const typeLabel = type => TYPES.find(t=>t.id===type)?.label || type;
const statusLabel = status => ({open:'Open','in-progress':'In progress',resolved:'Resolved'}[status]);
const currentCase = id => workspace.cases.find(item=>item.id===id);
const dirty = () => isWorkspaceDirty(workspace, savedSnapshot) || (vaultChanged && workspace.cases.length > 0);
const hasPendingWork = () => dirty() || hasDraftWork() || Boolean(latestEvidence || lastUrl);
const external = (url, label) => `<a href="${escape(url)}" target="_blank" rel="noopener noreferrer">${escape(label)} ↗</a>`;
const heading = (title,lead='',action='') => `<div class="page-head"><div><h1>${title}</h1>${lead?`<p class="lead">${lead}</p>`:''}</div>${action}</div>`;
const optional = '<span class="optional">optional</span>';
const errorBox = '<p class="error" role="alert" hidden></p>';
const sortedCases = () => [...workspace.cases].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));
const lockedNotice = () => vaultRaw&&!savedSnapshot?'<p class="notice">You have incidents saved in this browser, but they are locked. <a href="#vault">Unlock them</a></p>':'';
function notify(text, error=false) { clearTimeout(noticeTimer); const el=$('#notice'); el.textContent=text; el.hidden=false; el.classList.toggle('error-toast',error); noticeTimer=setTimeout(()=>{el.hidden=true;},6500); }
function showError(error, form) { const target=form?.querySelector('.error'); if(target?.isConnected){target.textContent=error.message || String(error);target.hidden=false;}else notify(error.message || String(error),true); }
function go(route) { if(location.hash===`#${route}`)render();else location.hash=route; }
function syncStatus(){ const state=$('#storage-state');const contextual=Boolean(workspace.cases.length||hasDraftWork()||savedSnapshot||vaultRaw||vaultChanged);state.hidden=!contextual;if(contextual)state.textContent=dirty()?'Unsaved changes':hasDraftWork()?'Unsaved draft':vaultChanged?'Saved data changed in another tab':savedSnapshot?'Encrypted copy saved':vaultRaw?'Saved vault locked':'Saved data changed in another tab'; }
function commit(next){ validateWorkspace(next); workspace=next;syncStatus(); }
function updateCase(id, action){ const next=structuredClone(workspace); const item=next.cases.find(c=>c.id===id);if(!item)throw Error('This incident is no longer in the workspace.');action(item);item.updatedAt=new Date().toISOString();commit(next); }
function caseRows(items){return `<ul class="case-list">${items.map(item=>`<li><a class="case-row" href="#case/${encodeURIComponent(item.id)}"><span><strong>${escape(item.title)}</strong><span class="meta">${escape(typeLabel(item.type))} · updated ${escape(date(item.updatedAt))}</span></span><span class="tag ${item.status}">${statusLabel(item.status)}</span></a></li>`).join('')}</ul>`;}
function emptyCases(){return `<div class="empty"><p><strong>No incidents yet.</strong> An incident keeps what happened, your file fingerprints and the response steps together.</p><a class="button" href="#new">Start an incident</a></div>`;}

const situations=[
 ['help/impersonation','Someone is pretending to be me','A fake profile, account or message using your name, photo or voice.'],
 ['help/deepfake','A photo, video or voice might be fake','Keep the original and check the story another way before you act.'],
 ['help/breach','Someone got into my account','Lock them out, keep records and recover from a device you trust.'],
 ['help/phishing','I clicked a link or gave out a password','Secure the account first, then keep the message.'],
 ['help/money','I sent money to someone','Call your bank on a number you already know, then keep the records.'],
 ['library','Something else, or I’m not sure','Short guides, official sources, and what this site can’t tell you.'],
];
const moreTools=[
 ['evidence','Fingerprint a file','Record a SHA-256 fingerprint so you can show later that a copy hasn’t changed.'],
 ['new','Keep an incident record','Write down what happened and tick off the response steps as you go.'],
 ['report','Report or recover an account','Official routes for YouTube, Instagram, Facebook, TikTok, X, Google and Microsoft.'],
 ['vault','Save or unlock your data','Encrypt your incidents with a passphrase. Keep them in this browser or as a backup file.'],
];
function markedUrl(result){const href=String(result.normalized||'');const host=result.hostname;const start=href.indexOf('//');if(!host||start<0)return escape(href);const rest=href.slice(start+2);const end=rest.search(/[/?#]/);const authority=end<0?rest:rest.slice(0,end);const from=start+2+authority.lastIndexOf('@')+1;const index=href.indexOf(host,from);if(index<0||index+host.length>start+2+authority.length)return escape(href);return `${escape(href.slice(0,index))}<mark>${escape(host)}</mark>${escape(href.slice(index+host.length))}`;}
function linkTool(){return `<form id="url-form" class="form"><div class="field"><label for="suspect-url">Link</label><textarea name="url" id="suspect-url" rows="3" required maxlength="8192" placeholder="https://…" spellcheck="false">${escape(drafts.url)}</textarea></div><div class="field"><label for="expected-domain">Which site did you expect? ${optional}</label><input name="expectedDomain" id="expected-domain" maxlength="253" value="${escape(drafts.expected)}" placeholder="for example yourbank.com" autocomplete="off" spellcheck="false"><p class="hint">Just the site name. Its subdomains count as a match.</p></div>${errorBox}<div class="form-actions"><button class="button" type="submit">Check link</button><span class="hint">This page never opens the link.</span></div></form><div id="url-result">${lastUrl?urlResult():''}</div>`;}
function urlResult(){const result=lastUrl.result;const warnings=result.findings.filter(f=>f.level!=='info').length;return `<section class="result" aria-labelledby="url-result-title"><h2 id="url-result-title">${result.hostname?'This link goes to':'No website address found'}</h2>${result.hostname?`<p class="destination"><mark>${escape(result.hostname)}</mark></p>`:''}<p class="full-url">${markedUrl(result)}</p><p class="hint">The highlighted part is the site that will open. Read it from the right: bank.com.example.net belongs to whoever owns example.net, not bank.com.</p><h3>${warnings?`${warnings} thing${warnings===1?'':'s'} to check`:'No listed warning'}</h3><ul class="findings">${result.findings.map(f=>`<li class="${f.level==='info'?'info':'warn'}"><strong>${escape(f.title)}</strong><span>${escape(f.detail)}</span></li>`).join('')}</ul><p class="hint">${escape(result.limitations)}</p><button class="button secondary" type="button" data-action="url-case">Save this as an incident</button></section>`;}
function fileTool(){return `<form id="hash-form" class="form"><div class="field"><label for="media-file">File</label><input id="media-file" name="file" type="file" required><p class="hint file-meta">${pendingFile?escape(pendingFile.name)+' · '+pendingFile.size.toLocaleString()+' bytes':'Any photo, video, audio or document up to 100 MiB.'}</p></div><div class="field"><label for="expected-hash">Compare with a fingerprint you already have ${optional}</label><input id="expected-hash" name="expected" placeholder="64 characters, 0–9 and a–f" pattern="[a-fA-F0-9]{64}" maxlength="64" value="${escape(drafts.fingerprint || '')}" autocomplete="off" spellcheck="false"><p class="hint">Only use a fingerprint from a source you trust separately.</p></div>${errorBox}<div class="form-actions"><button class="button" type="submit">Make fingerprint</button><span class="hint">The file is read on this device and never uploaded.</span></div></form><div id="hash-result">${latestEvidence?evidenceResult():''}</div>`;}
function evidenceResult(){const e=latestEvidence.record;const expected=latestEvidence.expected;const match=expected&&expected.toLowerCase()===e.sha256;const hasCases=workspace.cases.length>0;return `<section class="result" aria-labelledby="hash-result-title"><h2 id="hash-result-title">Fingerprint made</h2><p class="file-name">${escape(e.name || 'Unnamed file')}</p><code class="digest">${e.sha256}</code>${expected?`<p class="notice ${match?'match':'warn'}">${match?'The fingerprints match: these are the same bytes. That does not show the file is genuine.':'The fingerprints are different. This copy does not match the one you compared with.'}</p>`:''}<dl class="facts"><dt>Size</dt><dd>${e.size.toLocaleString()} bytes</dd><dt>Type reported by the browser</dt><dd>${escape(e.type || 'Not supplied')}</dd><dt>Made on this device</dt><dd>${escape(date(e.hashedAt))}</dd></dl><div class="form-actions"><button class="button secondary" type="button" data-action="download-fingerprint">Download fingerprint</button></div><form id="attach-form" class="form attach"><h3>Add it to an incident</h3>${hasCases?'':'<p>You don’t have an incident yet. <a href="#new">Start one</a> and come back: this fingerprint stays here while the tab is open.</p>'}<div class="field"><label for="attach-case">Incident</label><select id="attach-case" name="caseId" ${hasCases?'':'disabled'}>${workspace.cases.map(item=>`<option value="${escape(item.id)}" ${item.id===attachmentDraft.caseId?'selected':''}>${escape(item.title)}</option>`).join('') || '<option>Start an incident first</option>'}</select></div><div class="field"><label for="evidence-source">Where did you get this file? ${optional}</label><input id="evidence-source" name="sourceUrl" type="url" maxlength="2048" value="${escape(attachmentDraft.sourceUrl)}" placeholder="https://example.com/original-post"></div><div class="field"><label for="evidence-notes">How you got it ${optional}</label><textarea id="evidence-notes" name="notes" maxlength="10000" placeholder="When you received it, who sent it, whether it was edited or converted…">${escape(attachmentDraft.notes)}</textarea></div><div class="form-actions"><button class="button" type="submit" ${hasCases?'':'disabled'}>Add to incident</button></div></form></section>`;}
function linkPage(){return `${heading('Check a link without opening it','Paste a link from a message, email or post. This page reads the address on your device and never visits the site.')}${linkTool()}<p class="aside-note">These are clues about how the address is built, not a safety rating. A link with no warnings can still be dangerous.</p>`;}
function evidence(){return `${heading('Fingerprint a file','A SHA-256 fingerprint lets you show later that a copy of a photo, video or document has not changed. It does not tell you whether the file is fake.')}${lockedNotice()}${fileTool()}`;}
function overview(){const recent=sortedCases().slice(0,3);return `<div class="page-head"><div><h1>Help with scams, fakes and hacked accounts</h1><p class="lead">Free and private. Everything here runs in your browser: there is no account and nothing is uploaded.</p></div></div>${lockedNotice()}<section class="block" aria-labelledby="choose-title"><h2 id="choose-title">What’s going on?</h2><ul class="choices">${situations.map(([href,title,text])=>`<li><a href="#${href}"><strong>${title}</strong><span>${text}</span></a></li>`).join('')}</ul><p class="hint">If anyone is in immediate danger, contact local emergency services first.</p></section>${recent.length?`<section class="block" aria-labelledby="recent-title"><div class="section-head"><h2 id="recent-title">Your incidents</h2><a href="#cases">All incidents</a></div>${caseRows(recent)}</section>`:''}<section class="block band" aria-labelledby="link-title"><h2 id="link-title">Check a link without opening it</h2><p>Paste it here to see which website it really goes to.</p>${linkTool()}</section><section class="block" aria-labelledby="tools-title"><h2 id="tools-title">More tools</h2><ul class="tool-list">${moreTools.map(([href,title,text])=>`<li><a href="#${href}">${title}</a><p>${text}</p></li>`).join('')}</ul></section>`;}

function casesPage(){const note=vaultRaw&&!savedSnapshot?lockedNotice():`<p class="notice">${vaultRaw?'Changes stay in this tab until you <a href="#vault">save your data</a> again.':'Incidents only last while this tab is open. <a href="#vault">Save an encrypted copy</a> to keep them.'}</p>`;return `${heading('Incidents','Each incident keeps what happened, your file fingerprints and the response steps in one place.','<a class="button" href="#new">New incident</a>')}${note}${workspace.cases.length?caseRows(sortedCases()):emptyCases()}`;}
function caseForm(item, initialType=''){const edit=Boolean(item);if(!edit)drafts=startIncidentDraft(drafts,initialType);const draft=edit?{...item,...(caseEditDrafts[item.id]||{})}:drafts;const back=edit?'#case/'+encodeURIComponent(item.id):'#cases';return `<p class="back"><a href="${back}">← ${edit?'Back to incident':'All incidents'}</a></p>${heading(edit?'Edit incident':'New incident',edit?'':'Write down what you know now. You can change it later.')}<div class="split"><form id="case-form" class="form" ${edit?`data-id="${escape(item.id)}"`:''}><div class="field"><label for="case-title">Short title</label><input id="case-title" name="title" required maxlength="200" value="${escape(draft?.title)}" placeholder="for example: Fake account using my photos"></div><div class="field"><label for="case-type">What kind of incident?</label><select id="case-type" name="type" ${edit?'disabled':''}>${TYPES.map(t=>`<option value="${t.id}" ${draft?.type===t.id?'selected':''}>${t.label}</option>`).join('')}</select>${edit?'<p class="hint">The kind stays fixed so your ticked steps keep their meaning.</p>':''}</div><div class="field"><label for="case-source">Link to where it happened ${optional}</label><input id="case-source" name="sourceUrl" type="url" maxlength="2048" value="${escape(draft?.sourceUrl)}" placeholder="https://example.com/post"></div><div class="field"><label for="case-summary">What do you know so far? ${optional}</label><textarea id="case-summary" name="summary" rows="6" maxlength="10000" placeholder="What you saw, when it happened, and what still needs checking…">${escape(draft?.summary)}</textarea></div>${errorBox}<div class="form-actions"><button class="button" type="submit">${edit?'Save changes':'Create incident'}</button><a href="${back}" class="button secondary" ${edit?`data-action="cancel-edit" data-id="${escape(item.id)}"`:''}>Cancel</a></div></form><aside class="side"><h2>Tips</h2><p>Write down what you saw, not what you guess. Keep dates, the original messages and where each file came from.</p><p>Leave out passwords, recovery codes and other secrets.</p><p>While this tab is open your notes are not encrypted. <a href="#vault">Save your data</a> when you finish.</p><h2>Not ready to write it down?</h2><ul class="plain-list"><li><a href="#help/phishing">I clicked a link or gave out a password</a></li><li><a href="#help/money">I sent money to someone</a></li><li><a href="#help/impersonation">Someone is pretending to be me</a></li></ul></aside></div>`;}
function caseDetail(item){if(!item)return `${heading('Incident not found','It may be in a locked vault or in another tab.')}<a href="#vault" class="button">Open your data</a>`;const id=encodeURIComponent(item.id);const steps=PLAYBOOKS[item.type];return `<p class="back"><a href="#cases">← All incidents</a></p>${heading(escape(item.title),escape(typeLabel(item.type)))}<div class="actions-row"><a class="button" href="#report/${id}">Prepare a report</a><a class="button secondary" href="#edit/${id}">Edit</a><button class="button secondary" type="button" data-action="report" data-id="${escape(item.id)}">Download full record</button></div><div class="split"><div><section class="block first"><div class="section-head"><h2>Response steps</h2><p class="progress-label">${item.completedSteps.length} of ${steps.length} steps ticked</p></div><ul class="checklist">${steps.map(step=>`<li><label><input type="checkbox" data-case="${escape(item.id)}" data-step="${step.id}" ${item.completedSteps.includes(step.id)?'checked':''}><strong>${escape(step.title)}</strong></label><p>${escape(step.detail)}</p>${external(step.url,'Official guidance')}</li>`).join('')}</ul></section><section class="block"><div class="section-head"><h2>Evidence</h2><a href="#evidence">Add a file fingerprint</a></div>${item.evidence.length?`<ul class="evidence-list">${item.evidence.map(e=>`<li><strong>${escape(e.name)}</strong><code class="digest">${e.sha256}</code><p class="meta">${e.size.toLocaleString()} bytes · fingerprinted ${escape(date(e.hashedAt))}</p><p>Source: ${escape(e.sourceUrl || 'Not recorded')}</p><p>${escape(e.notes || 'No notes on how it was obtained.')}</p></li>`).join('')}</ul>`:'<p class="empty">No fingerprints yet. Keep the original files yourself: this site only stores their fingerprints.</p>'}</section></div><aside class="side"><h2>What you know</h2><p class="summary">${escape(item.summary || 'Nothing written yet.')}</p><dl class="facts"><dt>Created</dt><dd>${escape(date(item.createdAt))}</dd><dt>Updated</dt><dd>${escape(date(item.updatedAt))}</dd><dt>Link</dt><dd>${escape(item.sourceUrl || 'Not recorded')}</dd></dl><div class="field"><label for="case-status">Status</label><select id="case-status" data-case="${escape(item.id)}">${['open','in-progress','resolved'].map(s=>`<option value="${s}" ${s===item.status?'selected':''}>${statusLabel(s)}</option>`).join('')}</select><p class="hint">Your own note of progress, not a safety check.</p></div><p class="hint">Reports include your notes and links as plain text. Check them for personal details before you share them. Ticking steps does not mean you have recovered.</p><button class="link-button danger" type="button" data-action="delete" data-id="${escape(item.id)}">Delete this incident</button></aside></div>`;}

function vault(){const count=workspace.cases.length;return `${heading('Your data','Nothing is saved unless you save it. Keep an encrypted copy in this browser, or download an encrypted backup file.')}${hasDraftWork()?'<p class="notice warn">You have unfinished edits, tool inputs or a selected file. Saving keeps created incidents only, not drafts or files.</p>':''}<p class="state-line"><strong>${count} incident${count===1?'':'s'} open in this tab.</strong> ${dirty()?'Some changes are not saved.':savedSnapshot?'Everything matches your last save or the backup you opened.':'Nothing is saved automatically.'}</p><div class="split"><div><section class="block first" aria-labelledby="save-title"><h2 id="save-title">Save</h2><p>Choose a passphrase of at least 12 characters. There is no reset, so keep it somewhere safe.</p><form id="save-form" class="form"><div class="field"><label for="save-password">Passphrase</label><input id="save-password" name="password" type="password" autocomplete="new-password" minlength="12" maxlength="1024" required></div><div class="field"><label for="confirm-password">Type it again</label><input id="confirm-password" name="confirm" type="password" autocomplete="new-password" minlength="12" maxlength="1024" required></div>${errorBox}<div class="form-actions"><button class="button" type="submit" name="mode" value="local" ${storageAvailable?'':'disabled'}>Save in this browser</button><button class="button secondary" type="submit" name="mode" value="download">Download encrypted backup</button></div><p class="hint">Original files are never included. Download a backup before you clear your browser data.</p></form></section><section class="block" aria-labelledby="unlock-title"><h2 id="unlock-title">Unlock or restore</h2><form id="unlock-form" class="form"><div class="field"><label for="archive-file">Backup file ${optional}</label><input type="file" id="archive-file" name="archive" accept=".json,application/json"><p class="hint">Choose a backup, or leave this empty to unlock ${vaultRaw?'the copy saved in this browser.':'a copy saved in this browser (none found yet).'}</p></div><div class="field"><label for="unlock-password">Passphrase</label><input id="unlock-password" name="password" type="password" required minlength="12" maxlength="1024" autocomplete="current-password"></div>${errorBox}<div class="form-actions"><button class="button" type="submit">Unlock</button></div><p class="hint">You’ll be asked before anything in this tab is replaced. A wrong passphrase or damaged file changes nothing.</p></form></section></div><aside class="side"><h2>How it’s protected</h2><ul class="plain-list"><li>No accounts, analytics or uploads.</li><li>AES-256-GCM encryption with a key made from your passphrase by PBKDF2-SHA256 (600,000 iterations).</li><li>Your passphrase and the key are never stored.</li><li>While unlocked, incidents are readable in this tab. Encryption can’t protect a device or browser that is already compromised.</li></ul><h2>Clear this tab</h2><p>Removes open incidents and tool results from this tab. Data saved in this browser stays saved.</p><button class="button secondary" type="button" data-action="lock">Lock and clear</button><h2>Delete saved data</h2><p>Deletes the encrypted copy saved in this browser. Backup files and this tab are not affected.</p><button class="button danger" type="button" data-action="erase-vault" ${vaultRaw?'':'disabled'}>Delete saved copy</button></aside></div>`;}

const resources=[
 ['Someone is pretending to be you','Preserve the profile URL and messages. Use the affected platform’s impersonation reporting route. Verify unexpected requests using a number you already know.','https://consumer.ftc.gov/articles/scammers-use-fake-emergencies-steal-your-money','FTC · Impersonation and emergency scams'],
 ['A recording may be synthetic','Preserve the original, record its source and transformations, and confirm the surrounding context. Low quality alone does not establish manipulation.','https://www.nist.gov/document/deepfake-trifold-version','NIST · Examining deepfakes'],
 ['An account or system was compromised','Contain ongoing access, preserve relevant evidence, and recover through the organization’s incident process or the provider’s official recovery flow.','https://www.cisa.gov/stopransomware/ransomware-guide','CISA · Incident response guidance'],
 ['You need an incident response process','Use a documented process for analysis, containment, recovery, and follow-up. Organization and jurisdiction requirements vary.','https://www.cisa.gov/sites/default/files/publications/Cybersecurity_Incident_Vulnerability_Response_Playbooks_508C.pdf','CISA · Response playbooks (PDF)'],
 ['Report internet crime in the US','The FBI’s Internet Crime Complaint Center accepts internet-crime reports. This is a US route; elsewhere use the appropriate local authority.','https://www.ic3.gov/','FBI IC3 · US reporting'],
 ['Understand provenance','Content Credentials can describe provenance and modifications. Valid credentials do not prove truth; absent credentials do not prove a fake.','https://spec.c2pa.org/specifications/specifications/2.4/security/Harms_Modelling.html','C2PA · Harms and limitations'],
];
function library(){return `${heading('Guides and limits','Short advice with its official source, and a plain account of what this site can and cannot tell you.')}<p class="notice warn">You don’t need to prove something is a deepfake to stop and check. If someone is rushing you to pay or keep a secret, verify through a channel you already trust. If anyone is in immediate danger, contact local emergency services.</p><section class="block band" aria-labelledby="report-title"><h2 id="report-title">Report or recover an account</h2><p>Official routes for YouTube, Instagram, Facebook, TikTok, X, Google and Microsoft accounts. You choose what to share, and you send it yourself.</p><a class="button" href="#report">Find a reporting route</a></section><section class="block" aria-labelledby="advice-title"><h2 id="advice-title">Advice by situation</h2><ul class="guide-list">${resources.map(([title,body,url,label])=>`<li><h3>${title}</h3><p>${body}</p>${external(url,label)}</li>`).join('')}</ul></section><section class="block" aria-labelledby="limits-title"><h2 id="limits-title">What the results mean</h2><ul class="guide-list"><li><h3>File fingerprints</h3><p>A SHA-256 fingerprint shows whether two copies have exactly the same bytes. It does not prove who made a file, where it came from, or whether it is true. The time comes from your device.</p></li><li><h3>Link checks</h3><p>Warnings describe how the address is built, not the site’s reputation. A real site can be hacked, and a link with no warnings can still be harmful.</p></li><li><h3>AI detection</h3><p>This site does not run a deepfake detector or verify C2PA signatures, and it never gives probability scores. Checking the context yourself still matters most.</p>${external('https://www.ftc.gov/policy/advocacy-research/tech-at-ftc/2024/04/approaches-address-ai-enabled-voice-cloning','FTC · No single solution')}</li><li><h3>Privacy and source</h3><p>The tools work on your device. The host only sees ordinary page requests, and outside links open only when you choose them. The source code is MIT licensed and includes setup and test instructions.</p><a href="./usualcybersec-source.zip" download>Download the source</a></li></ul></section><p class="hint">Guidance reviewed 22 October 2026. Outside sources may change. This site never submits reports or contacts anyone for you.</p>`;}

function helpPage(kind){const titles={phishing:'If you clicked a link or gave out a password',money:'If you sent money',impersonation:'If someone is pretending to be you',deepfake:'If a photo, video or voice might be fake',breach:'If someone got into your account'};const type=kind==='money'?'deepfake':['deepfake','phishing','impersonation','breach'].includes(kind)?kind:'breach';const title=titles[kind]||'Respond to a security incident';const first=kind==='money'?'recover':kind==='phishing'?'secure':null;const steps=first?[PLAYBOOKS[type].find(x=>x.id===first),...PLAYBOOKS[type].filter(x=>x.id!==first)].filter(Boolean):PLAYBOOKS[type];return `<p class="back"><a href="#overview">← Home</a></p>${heading(title,'Follow these steps now. You don’t need an account or an incident record.')}<div class="split"><ol class="steps">${steps.map(step=>`<li><h2>${escape(step.title)}</h2><p>${escape(step.detail)}</p>${external(step.url,'Official guidance')}</li>`).join('')}</ol><aside class="side"><h2>Keep a record</h2><p>Write down what happened and tick off these steps as you go.</p><a href="#new/${type}" class="button">Start an incident</a><h2>Report it</h2><p><a href="#report">Find official reporting and recovery routes</a></p><p class="hint">Routes differ by country. If anyone is in immediate danger, contact local emergency services.</p></aside></div>`;}
function reportingPage() {
  const item=currentCase(reportingSelection.caseId);
  const issue=item?.type || reportingSelection.issue;
  const available=findReportingRoutes(issue);
  const selected=available.find(route=>route.id===reportingSelection.routeId);
  let packet='';
  if(item&&selected)packet=buildReportingPacket(item,selected.id,reportingSelection.disclosure);
  const routeDetails=selected?`<div class="route" aria-live="polite"><p class="tag">${selected.action==='recover'?'Account recovery':'Platform report'}</p><h3>${escape(selected.title)}</h3><p>${escape(selected.summary)}</p><h4>Before you start</h4><ul>${selected.requirements.map(requirement=>`<li>${escape(requirement)}</li>`).join('')}</ul><h4>Steps</h4><ol>${selected.steps.map(step=>`<li>${escape(step)}</li>`).join('')}</ol><p class="hint">${escape(selected.region)}</p>${selected.accessNote?`<p class="hint">${escape(selected.accessNote)}</p>`:''}<p class="hint">Source checked ${escape(selected.checkedAt)}. Requirements may change.</p><p>${external(selected.url,'Open the official page')}</p><p class="hint">It opens in a new tab. Nothing from usualCyberSec is sent to it.</p></div>`:'<p class="empty">Choose a service to see its official route and what it asks for.</p>';
  return `${heading('Report or recover an account','Find the official route, choose what to share, then send it yourself. This site never submits anything.')}
  <div class="split even"><section aria-labelledby="route-title"><h2 id="route-title">Choose a service</h2><form id="reporting-form" class="form">
    <div class="field"><label for="report-case">Incident ${optional}</label><select id="report-case" name="caseId"><option value="">Browse without an incident</option>${workspace.cases.map(entry=>`<option value="${escape(entry.id)}" ${entry.id===item?.id?'selected':''}>${escape(entry.title)}</option>`).join('')}</select><p class="hint">${workspace.cases.length?'Choosing a different incident clears your sharing choices.':'Start or unlock an incident when you want to prepare something to send.'}</p></div>
    <div class="field"><label for="report-issue">Situation</label><select id="report-issue" ${item?'disabled':''}><option value="all">All situations</option>${TYPES.map(type=>`<option value="${type.id}" ${issue===type.id?'selected':''}>${escape(type.label)}</option>`).join('')}</select></div>
    <div class="field"><label for="report-route">Service</label><select id="report-route"><option value="">Choose a service…</option>${available.map(route=>`<option value="${route.id}" ${route.id===selected?.id?'selected':''}>${escape(route.label)}</option>`).join('')}</select></div>
    ${routeDetails}
  </form></section><section aria-labelledby="packet-title"><h2 id="packet-title">What you’ll share</h2><p>See exactly what goes into the text you send. Nothing is submitted by this site.</p>
    ${item&&selected?`<form id="packet-form" class="form"><fieldset class="disclosure-fields"><legend>Add details from your incident</legend>${REPORT_FIELDS.map(field=>`<label for="disclose-${field.key}"><input type="checkbox" id="disclose-${field.key}" data-report-field="${field.key}" ${reportingSelection.disclosure[field.key]?'checked':''}>${escape(field.label)}</label>`).join('')}</fieldset><p class="hint" id="packet-privacy">Anything unticked stays out. Check your notes for private details. Links can contain personal identifiers or tracking codes.</p><div class="field"><label for="packet-preview">Preview</label><textarea id="packet-preview" class="packet-preview" readonly rows="16" aria-describedby="packet-privacy">${escape(packet)}</textarea></div>${errorBox}<div class="form-actions"><button class="button" type="submit">Download as text file</button></div><p class="hint">The download is not encrypted and contains no original files. Read it before you share it.</p></form>`:`<div class="empty"><p>${item?'Choose an official route to prepare a packet.':'Choose an incident to prepare a packet. You can read the official guidance without one.'}</p>${item?'':'<div class="form-actions"><a class="button secondary" href="#new">Start an incident</a><a href="#vault">Unlock saved incidents</a></div>'}</div>`}
  </section></div><p class="aside-note">These routes are options, not promises of removal, recovery or a reply. Describe what you saw and keep what you suspect apart from what you know.</p>`;
}
function changeReporting(target) {
  if(target.id==='report-case'){
    const item=currentCase(target.value);
    reportingSelection={caseId:item?.id||'',issue:item?.type||'all',routeId:'',disclosure:{}};
  } else if(target.id==='report-issue') {
    reportingSelection.issue=target.value;reportingSelection.routeId='';reportingSelection.disclosure={};
  } else if(target.id==='report-route') {
    reportingSelection.routeId=target.value;reportingSelection.disclosure={};
  } else if(target.dataset.reportField) {
    reportingSelection.disclosure[target.dataset.reportField]=target.checked;
  } else return false;
  const focusId=target.id;render();document.getElementById(focusId)?.focus({preventScroll:true});return true;
}
function render(){const raw=location.hash.slice(1)||'overview';const [route,encodedId]=raw.split('/');let id;try{id=decodeURIComponent(encodedId||'');}catch{id='';}if(route==='report'&&raw!==renderedRoute){resetReporting();const sourceCase=currentCase(id);if(sourceCase)reportingSelection={...reportingSelection,caseId:sourceCase.id,issue:sourceCase.type};}renderedRoute=raw;const views={overview,tools:linkPage,evidence,link:linkPage,cases:casesPage,new:()=>caseForm(undefined,id),help:()=>helpPage(id),report:reportingPage,case:()=>caseDetail(currentCase(id)),edit:()=>currentCase(id)?caseForm(currentCase(id)):caseDetail(null),vault,library};const known=Boolean(views[route]);const active=known?sections[route]:'overview';$('#navigation').innerHTML=routes.map(([key,label])=>`<a href="#${key}" ${active===key?'aria-current="page"':''}>${label}</a>`).join('');const vaultLink=$('#vault-link');if(active==='vault')vaultLink.setAttribute('aria-current','page');else vaultLink.removeAttribute('aria-current');document.title=`${known?pageTitles[route]:'Home'} · usualCyberSec`;$('#main').innerHTML=(known?views[route]:overview)();if(pendingFile&&$('#media-file')){const transfer=new DataTransfer();transfer.items.add(pendingFile);$('#media-file').files=transfer.files;}syncStatus();}
function download(content,filename,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function checkSource(source){if(!source)return '';const url=new URL(source);if(!['http:','https:'].includes(url.protocol))throw Error('Source URLs must start with http:// or https://.');return source;}
async function runForm(form, event){const data=new FormData(form);const value=key=>String(data.get(key)||'').trim();if(form.id==='case-form'){const title=value('title');if(!title)throw Error('Give this incident a title.');const sourceUrl=checkSource(value('sourceUrl'));const existing=currentCase(form.dataset.id);if(existing){updateCase(existing.id,item=>{item.title=title;item.summary=value('summary');item.sourceUrl=sourceUrl;});delete caseEditDrafts[existing.id];syncStatus();go('case/'+encodeURIComponent(existing.id));}else{const item=createCase({title,type:value('type'),summary:value('summary'),sourceUrl});commit({...workspace,cases:[item,...workspace.cases]});drafts={...drafts,title:'',summary:'',sourceUrl:'',type:'deepfake',initialized:false};go('case/'+encodeURIComponent(item.id));}notify('Incident saved in this session.');}
  if(form.id==='hash-form'){const file=data.get('file');if(!file?.name)throw Error('Choose a file first.');if(!crypto?.subtle)throw Error('File hashing requires HTTPS or localhost in a supported browser.');const ticket=++operation;const expected=value('expected');const record=await hashFile(file);if(ticket!==operation)return;latestEvidence={record,expected};if($('#hash-result'))$('#hash-result').innerHTML=evidenceResult();notify('Fingerprint created on this device.');}
  if(form.id==='attach-form'){if(!latestEvidence)throw Error('Fingerprint a file before attaching it.');const id=value('caseId');const sourceUrl=checkSource(value('sourceUrl'));updateCase(id,item=>item.evidence.push({...latestEvidence.record,id:crypto.randomUUID(),sourceUrl,notes:value('notes')}));resetAttachmentDraft();syncStatus();go('case/'+encodeURIComponent(id));notify('Fingerprint attached. Keep the original file separately.');}
  if(form.id==='url-form'){lastUrl={input:value('url'),expected:value('expectedDomain'),result:analyzeUrl(value('url'),value('expectedDomain'))};$('#url-result').innerHTML=urlResult();}
  if(form.id==='packet-form'){
    const item=currentCase(reportingSelection.caseId);
    if(!item)throw Error('Choose an incident before downloading a packet.');
    const route=getReportingRoute(reportingSelection.routeId);
    if(!route)throw Error('Choose an official reporting or recovery route.');
    const packet=buildReportingPacket(item,route.id,reportingSelection.disclosure);
    download(packet,`usualcybersec-packet-${route.id}-${item.id}.txt`,'text/plain;charset=utf-8');
    notify('Packet download started. Review it before sending it to the service.');
  }
  if(form.id==='save-form'){const password=String(data.get('password'));if(password!==String(data.get('confirm')))throw Error('The passphrases do not match.');const snapshot=JSON.stringify(workspace);const mode=event.submitter?.value || 'local';const baseline=mode==='local'?localStorage.getItem(storageKey):null;if(mode==='local'){const current=baseline;if(current&&(!savedSnapshot||current!==vaultRaw)&&!confirm('Saving replaces the encrypted vault currently stored in this browser. Continue?'))return;}const envelope=await encryptWorkspace(JSON.parse(snapshot),password);const serialized=JSON.stringify(envelope);if(mode==='local'){await saveCiphertext(localStorage,navigator.locks,storageKey,baseline,serialized);vaultRaw=serialized;savedSnapshot=snapshot;vaultChanged=false;notify('Encrypted vault saved in this browser.');}else{download(serialized,'usualcybersec-backup-'+new Date().toISOString().slice(0,10)+'.json');notify('Encrypted backup download started. Verify it is saved before closing.');}form.reset();if(mode==='local'&&location.hash==='#vault')render();else syncStatus();}
  if(form.id==='unlock-form'){const file=data.get('archive');const {raw,fromFile}=await readArchiveInput(file,file?.name?null:localStorage.getItem(storageKey));let decrypted;try{decrypted=await decryptWorkspace(JSON.parse(raw),String(data.get('password')));}catch{throw Error('Cannot unlock this archive. Check the passphrase and use an unmodified usualCyberSec backup. The current session is unchanged.');}if((workspace.cases.length||hasPendingWork())&&!confirm('Replace the current session with this archive? Unsaved session changes will be lost.'))return;commit(decrypted);savedSnapshot=fromFile?null:JSON.stringify(decrypted);if(!fromFile){vaultRaw=raw;vaultChanged=false;}latestEvidence=null;lastUrl=null;pendingFile=null;drafts=emptyDraft();caseEditDrafts=Object.create(null);resetAttachmentDraft();resetReporting();operation++;form.reset();go('cases');notify('Workspace unlocked on this device.');}
}
document.addEventListener('submit',async event=>{event.preventDefault();if(busy)return;const form=event.target;const buttons=[...form.querySelectorAll('button')];const disabled=buttons.map(b=>b.disabled);buttons.forEach(b=>b.disabled=true);form.setAttribute('aria-busy','true');busy=true;const error=form.querySelector('.error');if(error)error.hidden=true;try{await runForm(form,event);}catch(err){showError(err,form);}finally{busy=false;form.removeAttribute('aria-busy');buttons.forEach((b,i)=>b.disabled=disabled[i]);}});
document.addEventListener('change',event=>{const target=event.target;if(target.closest('#reporting-form,#packet-form')){try{if(changeReporting(target))return;}catch(error){notify(error.message,true);return;}}if(target.id==='attach-case')attachmentDraft.caseId=target.value;if(target.id==='media-file'){resetAttachmentDraft();operation++;pendingFile=target.files[0]||null;latestEvidence=null;if($('#hash-result'))$('#hash-result').innerHTML='';const meta=$('.file-meta');if(meta)meta.textContent=pendingFile?pendingFile.name+' · '+pendingFile.size.toLocaleString()+' bytes':'No file selected';}if(target.id==='case-type'&&!target.closest('form').dataset.id){drafts.type=target.value;drafts.initialized=true;}syncStatus();if(busy){if(target.matches('[data-step],#case-status'))render();return;}try{if(target.matches('[data-step]')){updateCase(target.dataset.case,item=>{item.completedSteps=target.checked?[...item.completedSteps,target.dataset.step]:item.completedSteps.filter(step=>step!==target.dataset.step);});const item=currentCase(target.dataset.case);$('.progress-label').textContent=`${item.completedSteps.length} of ${PLAYBOOKS[item.type].length} steps ticked`;}if(target.id==='case-status'){updateCase(target.dataset.case,item=>item.status=target.value);notify('Status recorded in this session.');}}catch(error){notify(error.message,true);render();}});
document.addEventListener('click',async event=>{const skip=event.target.closest('.skip');if(skip){event.preventDefault();const main=$('#main');main.focus({preventScroll:true});main.scrollIntoView();return;}const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;const id=button.dataset.id;if(action==='cancel-edit'){delete caseEditDrafts[id];syncStatus();return;}if(busy){notify('Wait for the current operation to finish.');return;}try{if(action==='report'){const item=currentCase(id);download(exportReport(item),'usualcybersec-incident-'+item.id.replace(/[^a-zA-Z0-9-]/g,'').slice(0,36)+'.md','text/markdown');notify('Report download started. Review personal information before sharing.');}if(action==='download-fingerprint'&&latestEvidence)download(JSON.stringify({tool:'usualCyberSec',...latestEvidence.record,limitations:'Identifies matching bytes only. Does not prove authenticity.'},null,2),'usualcybersec-fingerprint.json');if(action==='url-case'&&lastUrl){const item=createCase({title:'Review: '+(lastUrl.result.hostname||'suspicious link'),type:'phishing',sourceUrl:'',summary:'Submitted URL (unvisited): '+lastUrl.input+'\n\n'+lastUrl.result.findings.map(f=>f.title+': '+f.detail).join('\n')+'\n\n'+lastUrl.result.limitations});commit({...workspace,cases:[item,...workspace.cases]});go('case/'+encodeURIComponent(item.id));}if(action==='delete'&&confirm('Delete this incident from the session, including its fingerprint records? Saved backups are unchanged.')){commit({...workspace,cases:workspace.cases.filter(item=>item.id!==id)});delete caseEditDrafts[id];if(attachmentDraft.caseId===id)attachmentDraft.caseId='';syncStatus();go('cases');notify('Incident deleted from this session. Save again to update your vault.');}if(action==='lock'){if(hasPendingWork()&&!confirm('Clear the session now? Unsaved cases and pending review results will be lost. Saved vaults and downloaded backups remain.'))return;workspace={version:1,cases:[]};savedSnapshot=null;latestEvidence=null;lastUrl=null;pendingFile=null;drafts=emptyDraft();caseEditDrafts=Object.create(null);resetAttachmentDraft();resetReporting();operation++;render();notify('Session cleared. Saved encrypted data is unchanged.');}if(action==='erase-vault'&&confirm('Permanently delete the encrypted vault saved in this browser? Download a backup first if you need it.')){await eraseCiphertext(localStorage,navigator.locks,storageKey);vaultRaw=null;vaultChanged=false;savedSnapshot=null;render();notify('Saved browser vault deleted.');}}catch(err){notify(err.message,true);}});
document.addEventListener('input',event=>{
  const target=event.target;
  if(target.id==='expected-hash'){operation++;drafts.fingerprint=target.value;latestEvidence=null;if($('#hash-result'))$('#hash-result').innerHTML='';}
  if(target.id==='suspect-url')drafts.url=target.value;
  if(target.id==='expected-domain')drafts.expected=target.value;
  if(['suspect-url','expected-domain'].includes(target.id)){lastUrl=null;if($('#url-result'))$('#url-result').innerHTML='';}
  const form=target.closest('form');
  if(form?.id==='case-form'){
    const id=form.dataset.id;
    if(id&&['title','summary','sourceUrl'].includes(target.name)){
      const edit=caseEditDrafts[id]||{};
      const original=currentCase(id)?.[target.name];
      if(target.value===original)delete edit[target.name];else edit[target.name]=target.value;
      if(Object.keys(edit).length)caseEditDrafts[id]=edit;else delete caseEditDrafts[id];
    }else if(!id&&['title','summary','sourceUrl'].includes(target.name))drafts[target.name]=target.value;
  }
  if(form?.id==='attach-form'&&['sourceUrl','notes'].includes(target.name))attachmentDraft[target.name]=target.value;
  syncStatus();
});
window.addEventListener('hashchange',()=>{render();$('#main').focus({preventScroll:true});window.scrollTo(0,0);});
window.addEventListener('beforeunload',event=>{if(hasPendingWork()||busy){event.preventDefault();event.returnValue='';}});
window.addEventListener('storage',event=>{if(event.key===storageKey){notify('The saved vault changed in another tab. Download a backup before unlocking its latest copy.');vaultChanged=true;syncStatus();}});
render();
if(!storageAvailable)notify('Browser storage is unavailable. Use encrypted backup downloads.',true);
